const mongoose = require('mongoose');

// Lightweight viewer record (no registration): created the first time an
// anonymous browser likes or comments. viewerId is generated by the frontend.
const viewerSchema = new mongoose.Schema(
  {
    viewerId: { type: String, required: true, unique: true },
    displayName: { type: String, default: '', trim: true, maxlength: 40 },
    lastActiveAt: { type: Date, default: Date.now },
  },
  { timestamps: true }
);

module.exports = mongoose.model('Viewer', viewerSchema);
